(() => { const c=window.ATLAS_CONTENT; document.querySelectorAll('[data-checkout="principal"]').forEach(a=>a.href=c.checkout.principal);document.querySelectorAll('[data-checkout="completo"]').forEach(a=>a.href=c.checkout.completo);document.querySelectorAll('[data-loop]').forEach(t=>{[...t.children].forEach(x=>{const clone=x.cloneNode(true);clone.setAttribute('aria-hidden','true');t.append(clone);});t.setAttribute('aria-live','off');});document.querySelectorAll('[data-play-video]').forEach(button=>button.addEventListener('click',()=>{const video=document.getElementById(button.dataset.playVideo);if(video){video.muted=false;video.scrollIntoView({block:'center',behavior:'smooth'});video.play().catch(()=>video.focus());}}));document.querySelectorAll('[data-enable-video-sound]').forEach(button=>button.addEventListener('click',()=>{const video=document.getElementById(button.dataset.enableVideoSound);if(video){video.muted=false;video.play().catch(()=>video.focus());button.hidden=true;}}));const preview=document.querySelector('[data-scroll-preview]');if(preview&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting&&entry.intersectionRatio>=.55){preview.muted=true;preview.play().catch(()=>{});}else{preview.pause();}}),{threshold:[0,.55]});observer.observe(preview);}})();

